SELECT id, name, asset_code, category, manufacturer, purchase_date, warranty_expiration, location, quantity, available_quantity, max_rental_quantity, is_rentable, is_retired, managed_by, status, description, image_path, created_at, updated_at FROM equipment
AND ( name LIKE CONCAT('%', #{keyword}, '%') OR manufacturer LIKE CONCAT('%', #{keyword}, '%') OR asset_code LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%') )
AND category = #{category}
AND status = #{status}
AND location = #{location}
AND (is_retired = false OR is_retired IS NULL)
ORDER BY created_at ASC
ORDER BY name ASC
ORDER BY category ASC, name ASC
ORDER BY available_quantity DESC, name ASC
ORDER BY created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM equipment


        AND (
            name LIKE CONCAT('%', #{keyword}, '%') 
            OR manufacturer LIKE CONCAT('%', #{keyword}, '%')
            OR asset_code LIKE CONCAT('%', #{keyword}, '%')
            OR description LIKE CONCAT('%', #{keyword}, '%')
        )


        AND category = #{category}


        AND status = #{status}


        AND location = #{location}


    AND (is_retired = false OR is_retired IS NULL)

